import java.util.*;

class Solution {
  private String expression;
  private int index;

  public List<String> braceExpansionII(String expression) {
    this.expression = expression;
    this.index = 0;
    return new ArrayList<>(parseExpression());
  }

  private Set<String> parseExpression() {
    Set<String> result = parseConcatenation();
    while (index < expression.length() && expression.charAt(index) == ',') {
      index++;
      result.addAll(parseConcatenation());
    }
    if (index < expression.length() && expression.charAt(index) == '}') index++;
    return result;
  }

  private Set<String> parseConcatenation() {
    Set<String> result = new TreeSet<>();
    result.add("");
    while (index < expression.length()
        && expression.charAt(index) != '}'
        && expression.charAt(index) != ',') {
      Set<String> term = expression.charAt(index) == '{' ? parseGroup() : parseWord();
      Set<String> combined = new TreeSet<>();
      for (String prefix : result) for (String suffix : term) combined.add(prefix + suffix);
      result = combined;
    }
    return result;
  }

  private Set<String> parseGroup() {
    index++;
    return parseExpression();
  }

  private Set<String> parseWord() {
    Set<String> word = new TreeSet<>();
    StringBuilder value = new StringBuilder();
    while (index < expression.length() && Character.isLetter(expression.charAt(index)))
      value.append(expression.charAt(index++));
    word.add(value.toString());
    return word;
  }
}
